Lemma nullbase_xor_pos : forall b s, 0 < b -> 0 < s -> Z.lxor (Z.b2z (0 <? b)) (Z.b2z (s <? 1)) = 1.
Proof.
  intros b s Hb Hs. destruct (Z.ltb_spec 0 b); destruct (Z.ltb_spec s 1); cbn; first [reflexivity | exfalso; lia].
Qed.

