Definition svat_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (SV p n i : Z) (rest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (p + i)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' SV (C8 (wz p) :: C8 (wz n) :: rest).

Definition svat_stmt : Prop := forall (SV p n i : Z) (rest : list cell) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m SV (C8 (wz p) :: C8 (wz n) :: rest) ->
  0 <= i < n -> 0 <= p -> p + n < 2^64 ->
  stk usegs m lo (bv_unsigned sp) -> lo + SV_LEAF_STACK <= bv_unsigned sp ->
  (bv_unsigned sp <= SV \/ SV + Z.of_nat (cells_size (C8 (wz p) :: C8 (wz n) :: rest)) <= lo) ->
  0 < p ->                                                                    (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (svat_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SV p n i rest lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz SV) (wz i) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SV_INDEX) fc None m (seg_rom usegs)).
